-- Official international ISIC Rev.4 structure seed (766 hierarchy rows)
-- Source: https://unstats.un.org/unsd/classifications/Econ/Download/In%20Text/ISIC_Rev_4_english_structure.Txt
-- IMPORTANT: This is VARIANT_CODE='UNSD', not the Iranian national adaptation.
-- NAME_EN is official UNSD text. NAME_FA is NULL except explicitly bank-verified project labels.

MERGE INTO CIF.REF_ISIC_RELEASE T
USING (SELECT 'ISIC' CLASSIFICATION_CODE, '4' REVISION_CODE, 'UNSD' VARIANT_CODE FROM DUAL) S
ON (T.CLASSIFICATION_CODE=S.CLASSIFICATION_CODE AND T.REVISION_CODE=S.REVISION_CODE AND T.VARIANT_CODE=S.VARIANT_CODE)
WHEN MATCHED THEN UPDATE SET T.NAME_EN='International Standard Industrial Classification of All Economic Activities, Revision 4', T.SOURCE_AUTHORITY='United Nations Statistics Division', T.SOURCE_URI='https://unstats.un.org/unsd/classifications/Econ/Download/In%20Text/ISIC_Rev_4_english_structure.Txt', T.DATASET_STATUS_CODE='COMPLETE', T.IS_ACTIVE=1, T.LAST_MODIFIED_BY='SEED', T.LAST_MODIFIED_DATE=SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT (CLASSIFICATION_CODE,REVISION_CODE,VARIANT_CODE,COUNTRY_CODE,NAME_FA,NAME_EN,SOURCE_AUTHORITY,SOURCE_URI,DATASET_STATUS_CODE,IS_CURRENT,IS_ACTIVE,RECORD_VERSION,CREATED_BY) VALUES ('ISIC','4','UNSD',NULL,NULL,'International Standard Industrial Classification of All Economic Activities, Revision 4','United Nations Statistics Division','https://unstats.un.org/unsd/classifications/Econ/Download/In%20Text/ISIC_Rev_4_english_structure.Txt','COMPLETE',0,1,1,'SEED');

MERGE INTO CIF.REF_ISIC_ACTIVITY2 T
USING (SELECT R.ISIC_RELEASE_ID FROM CIF.REF_ISIC_RELEASE R WHERE R.CLASSIFICATION_CODE='ISIC' AND R.REVISION_CODE='4' AND R.VARIANT_CODE='UNSD') S
ON (T.ISIC_RELEASE_ID=S.ISIC_RELEASE_ID AND T.ISIC_CODE='A')
WHEN MATCHED THEN UPDATE SET T.BASE_ISIC_CODE=NULL, T.LEVEL_CODE='SECTION', T.PARENT_ISIC_CODE=NULL, T.SECTION_CODE='A', T.NAME_FA=NULL, T.NAME_EN='Agriculture, forestry and fishing', T.TRANSLATION_STATUS='NOT_AVAILABLE', T.IS_SELECTABLE=0, T.IS_ACTIVE=1, T.SORT_ORDER=10, T.LAST_MODIFIED_BY='SEED', T.LAST_MODIFIED_DATE=SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT (ISIC_RELEASE_ID,ISIC_CODE,BASE_ISIC_CODE,LEVEL_CODE,PARENT_ISIC_CODE,SECTION_CODE,NAME_FA,NAME_EN,TRANSLATION_STATUS,IS_SELECTABLE,IS_ACTIVE,SORT_ORDER,RECORD_VERSION,CREATED_BY) VALUES (S.ISIC_RELEASE_ID,'A',NULL,'SECTION',NULL,'A',NULL,'Agriculture, forestry and fishing','NOT_AVAILABLE',0,1,10,1,'SEED');

